let toastTimeout;
function toast(message,error=false){const e=$('#toast');e.className=(error?'visible error':'visible');e.textContent=message;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>e.className='',3300)}
async function api(path,opt={}){
 const settings={credentials:'same-origin',...opt};
 if(opt.body&&!(opt.body instanceof FormData)) {settings.headers={'Content-Type':'application/json',...(settings.headers||{})};settings.body=typeof opt.body==='string'?opt.body:JSON.stringify(opt.body)}
 let r=await fetch('/api'+path,settings);
 let text=await r.text();let data;try{data=JSON.parse(text)}catch{data={detail:text}}
 if(!r.ok){let m=typeof data.detail==='string'?data.detail:JSON.stringify(data.detail);if(r.status===401){S.user=null;render()}throw Error(m||('HTTP '+r.status))}
 return data;
}
