function heading(title,subtitle,extra=''){return `<div class="page-heading"><div><h2>${title}</h2><p>${subtitle}</p></div><div class="actions">${extra}</div></div>`}
function page(){switch(S.view){case 'analysis-detail':return analysisDetail(S.intelTab??1,S.intelCard||0);case 'intelligence':return intelligencePage();case 'dashboard':return dash();case 'map':return mapPage();case 'areas':return areaList();case 'area':return areaPage();case 'alerts':return alertsPage();case 'predictions':return predictionsPage();case 'tasks':return tasksPage();case 'reports':return reportsPage();case 'settings':return settingsPage();default:return dash()}}
function stat(label,value,theme,ic,sub='',tk=''){return `<div class="surface stat-card theme-${theme}"><div class="stat-icon">${icon(ic,20)}</div><div class="stat-label">${label} ${tk?tip(tk):''}</div><div class="stat-number ${typeof value==='number'?'':'stat-text'}">${esc(value)}</div><div class="stat-side">${sub}</div></div>`}
