function alertRows(max){const alerts=S.data.alerts.filter(x=>x.status!=='closed').slice(0,max);if(!alerts.length)return empty();return alerts.map(a=>{const site=getArea(a.area_id);return `<div class="list-row"><span class="list-mark">${icon('triangle-alert',17)}</span><div class="list-main"><b>${site?esc(areaLabel(site)):'—'}</b><small>${esc(alertLabel(a))}</small></div>${badge(a.severity)}</div>`}).join('')}
function selectedArea(){return S.data?.areas.find(x=>x.id===S.areaId)||S.data?.areas[0]||null}
function getArea(id){return S.data?.areas.find(x=>x.id===id)}
function chart(numbers,hero=false){numbers=numbers.filter(x=>Number.isFinite(x));if(!numbers.length)return `<div class="empty">${t('empty')}</div>`;
 const width=640,height=165,pad=19;let lo=Math.min(...numbers)-.08,hi=Math.max(...numbers)+.08;lo=Math.max(-1,lo);hi=Math.min(1,hi);if(hi===lo)hi=lo+.01;
 const pts=numbers.map((y,i)=>({x:pad+(width-pad*2)*(numbers.length===1?0:i/(numbers.length-1)),y:height-pad-(y-lo)/(hi-lo)*(height-pad*2)}));
 const poly=pts.map(p=>`${p.x},${p.y}`).join(' ');const fillpoly=`${pad},${height-pad} ${poly} ${pts.at(-1).x},${height-pad}`;
 return `<svg class="chart-svg ${hero?'demo-spark':''}" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="NDVI trend">
  <defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${hero?'#9bdfba':'#63c99a'}" stop-opacity=".24"/><stop offset="100%" stop-color="#6bc79e" stop-opacity="0"/></linearGradient></defs>
  ${[1,2,3].map(i=>`<line x1="${pad}" y1="${i*height/4}" x2="${width-pad}" y2="${i*height/4}" stroke="${hero?'#ffffff21':'#eaf0eb'}" stroke-dasharray="4 5"/>`).join('')}
  <polygon points="${fillpoly}" fill="url(#chartFill)"/><polyline points="${poly}" fill="none" stroke="${hero?'#9ee5bc':'#279775'}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>
  ${pts.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="${i===pts.length-1?5:3}" stroke="${hero?'#275f46':'#fff'}" stroke-width="2" fill="${hero?'#b4f2cb':'#28916f'}"/>`).join('')}
 </svg>`}
function trendBlock(a){const valid=RawaaAnalysis.observations(a);if(!valid.length)return empty();return `${chart(valid.map(x=>x.ndvi))}<div class="chart-foot"><span>${dt(valid[0].measured_at)}</span><span>${t('latest')}: <b style="color:#1b8865">${fmt(a.metrics.current_ndvi)}</b></span><span>${dt(valid.at(-1).measured_at)}</span></div>`}
/* Copernicus Browser (Copernicus Data Space Ecosystem): works without server keys. Builds a deep link that opens
   the exact area, Sentinel-2 L2A dataset, month and layer chosen in RAWAA. */
const COP_BROWSER='https://browser.dataspace.copernicus.eu/';
const COP_VIS='U2FsdGVkX1/zz8HXN+cLZmDvMHZlSkJyRf9w4FKQzbVp0wC7Q8paWnUd340AOhDCjiR439MrNVzvf18p7ySa7aD1eWD94hT7twTreLn/QDLvbtyNlU1W48Y+4hE6P2MH';
const COP_LAYERS={ndvi:'3_NDVI',true_color:'1_TRUE_COLOR',false_color:'2_FALSE_COLOR',urban:'4-FALSE-COLOR-URBAN',moisture:'5-MOISTURE-INDEX1',swir:'6-SWIR',ndwi:'7-NDWI',ndre:'3_NDVI'};
/* Sentinel-2 layers rendered inside RAWAA through the server (Copernicus Process API). */
const S2_LAYERS=[
 ['true_color','ألوان حقيقية','True color','B4, B3, B2','',''],
 ['false_color','ألوان كاذبة (نبات)','False color (vegetation)','B8, B4, B3','النبات السليم أحمر فاتح؛ الضعيف أغمق أو بني.','Healthy vegetation bright red; weak vegetation darker or brown.'],
 ['ndvi','مؤشر NDVI','NDVI','(B8 − B4)/(B8 + B4)','أحمر < 0.08 · برتقالي 0.08–0.20 · أصفر 0.20–0.35 · أخضر 0.35–0.55 · أخضر داكن ≥ 0.55','Red < 0.08 · orange 0.08–0.20 · yellow 0.20–0.35 · green 0.35–0.55 · dark green ≥ 0.55'],
 ['ndre','مؤشر الحافة الحمراء NDRE (الكلوروفيل)','NDRE (red edge / chlorophyll)','(B8A − B5)/(B8A + B5)','أحمر < 0.15 ضعيف · أصفر ~0.3 · أخضر ≥ 0.45 كلوروفيل جيد','Red < 0.15 low · yellow ~0.3 · green ≥ 0.45 good chlorophyll'],
 ['moisture','مؤشر الرطوبة (NDMI)','Moisture index (NDMI)','(B8A − B11)/(B8A + B11)','أحمر/أصفر = جفاف وإجهاد مائي · سماوي/أزرق = رطوبة جيدة','Red/yellow = dry, water stress · cyan/blue = good moisture'],
 ['ndwi','مؤشر الماء NDWI','NDWI (water)','(B3 − B8)/(B3 + B8)','أخضر = نبات · أبيض = تربة · أزرق = ماء أو تشبّع مائي','Green = vegetation · white = soil · blue = water or waterlogging'],
 ['swir','SWIR','SWIR','B12, B8A, B4','النبات أخضر، التربة الرطبة داكنة، الجافة فاتحة.','Vegetation green, wet soil dark, dry soil bright.'],
 ['urban','ألوان كاذبة (حضري)','False color (urban)','B12, B11, B4','يميّز الأسفلت والمباني عن الغطاء النباتي.','Separates asphalt and buildings from vegetation.']];
const s2Layer=k=>S2_LAYERS.find(x=>x[0]===k);
function areaCenter(a){try{const pts=a.geometry.coordinates.flat();const xs=pts.map(p=>+p[0]),ys=pts.map(p=>+p[1]);return [(Math.min(...ys)+Math.max(...ys))/2,(Math.min(...xs)+Math.max(...xs))/2]}catch(e){return [21.553,39.187]}}
function copernicusBrowserUrl(a,layer='ndvi',month=S.mapMonth){
 const [lat,lng]=a?areaCenter(a):[21.553,39.187];const now=new Date();
 let m=/^\d{4}-\d{2}$/.test(month||'')?month:now.toISOString().slice(0,7);
 const start=new Date(m+'-01T00:00:00Z');let end=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0,23,59,59,999));if(end>now)end=now;
 const q=new URLSearchParams({zoom:a?'16':'12',lat:lat.toFixed(5),lng:lng.toFixed(5),themeId:'DEFAULT-THEME',visualizationUrl:COP_VIS,datasetId:'S2_L2A_CDAS',fromTime:start.toISOString(),toTime:end.toISOString(),layerId:COP_LAYERS[layer]||COP_LAYERS.ndvi,demSource3D:'"MAPZEN"',cloudCoverage:'30',dateMode:'SINGLE'});
 return COP_BROWSER+'?'+q.toString()}
function copLink(a,layer,label,cls='btn'){return `<a class="${cls}" href="${esc(copernicusBrowserUrl(a,layer))}" target="_blank" rel="noopener">${icon('satellite',15)} ${label}</a>`}
function copernicusPanel(a){if(!a)return '';return `<div class="surface cop-panel"><div class="cop-head"><div class="stat-icon" style="margin:0;background:#eaf7ee;color:#187d5b">${icon('satellite',20)}</div><div><b>Copernicus Browser · Sentinel-2 L2A</b><p class="muted">${ar()?`${esc(areaLabel(a))} · فترة ${esc(S.mapMonth)} · غيوم ≤ 30%`:`${esc(areaLabel(a))} · period ${esc(S.mapMonth)} · clouds ≤ 30%`}</p></div><span class="status stable">${ar()?'مفعّل':'Active'}</span></div>
 <div class="cop-actions">${copLink(a,'ndvi',ar()?'NDVI للمنطقة':'Area NDVI','btn primary')}${copLink(a,'true_color',ar()?'ألوان حقيقية':'True color')}${copLink(a,'false_color',ar()?'ألوان كاذبة (نبات)':'False color (vegetation)')}${copLink(a,'moisture',ar()?'مؤشر الرطوبة':'Moisture index')}</div>
 <p class="help-note" style="margin-top:12px">${ar()?'تفتح المنصة الرسمية Copernicus Browser على حدود المنطقة نفسها وبالشهر المختار. للاطلاع على الصور لا تحتاج مفاتيح؛ قد يُطلب تسجيل دخول مجاني لبعض الأدوات مثل التنزيل والسلاسل الزمنية.':'Opens the official Copernicus Browser on this area for the chosen month. Viewing needs no keys; a free login may be required for tools like download and time series.'}</p></div>`}
