 <div style="display:flex;gap:14px;align-items:center;margin:25px 0"><div class="stat-icon" style="margin:0;background:#eaf7ee;color:#187d5b">${icon('satellite-dish',22)}</div><div><b>Copernicus Data Space</b><p class="muted" style="font-size:12px;margin:5px 0">Sentinel Hub · Statistical API</p></div><div style="margin-inline-start:auto">${S.data.integration?badge('stable'):badge('insufficient')}</div></div>
